abstract class StatefulProduct {
    protected final String id;
    StatefulProduct(String id) { this.id = id; validate(); }
    protected void validate() { if (id.isBlank()) throw new IllegalArgumentException(); }
    abstract String type();
}
class StatefulOrtho extends StatefulProduct {
    StatefulOrtho(String id) { super(id); }
    String type() { return "ortho"; }
}
public class PreferAbstractClassDemo {
    public static void main(String[] args) { var p = new StatefulOrtho("O1"); System.out.println(p.type() + ":" + p.id); }
}
